@font-face {
  font-family: "TH Sarabun Document";
  src: url("/assets/connect_diagnostics_core/fonts/THSarabun.ttf") format("truetype");
  font-style: normal;
  font-weight: 400;
}

@page {
  size: 210mm 297mm;
  margin: 0;
}

html,
body {
  margin: 0 !important;
  padding: 0 !important;
}

.print-format {
  width: 210mm !important;
  min-height: 297mm !important;
  margin: 0 !important;
  padding: 0 !important;
}

.cd-po,
.cd-po * {
  box-sizing: border-box;
}

.cd-po {
  position: relative;
  width: 210mm;
  height: 297mm;
  margin: 0;
  overflow: hidden;
  color: #181818;
  background: #fff;
  font-family: "TH Sarabun Document", "TH SarabunPSK", sans-serif;
  font-size: 4.22mm;
  font-weight: 400;
  line-height: 1;
  page-break-after: always;
  -webkit-print-color-adjust: exact;
  print-color-adjust: exact;
}

.cd-po.last-page {
  page-break-after: auto;
}

.cd-po .th,
.cd-po .en {
  display: block;
  white-space: nowrap;
}

.cd-po .th {
  font-size: 4.22mm;
  line-height: 3.7mm;
}

.cd-po .en {
